// 알림 단계 분류
const items = $input.all();
const results = [];

for (const item of items) {
    const days = item.json.days_remaining;
    let stage = '';
    let urgency = '';

    if (days >= 75) {
        stage = 'D-90';
        urgency = '정보';
    } else if (days >= 50) {
        stage = 'D-60';
        urgency = '주의';
    } else if (days >= 25) {
        stage = 'D-30';
        urgency = '긴급';
    } else if (days >= 10) {
        stage = 'D-14';
        urgency = '매우긴급';
    } else {
        stage = 'D-7';
        urgency = '최종경고';
    }

    const endDate = new Date(item.json.end_date);
    const formattedDate = endDate.toLocaleDateString('ko-KR');
    const amount = parseInt(item.json.monthly_amount || 0).toLocaleString('ko-KR');

    results.push({
        json: {
            ...item.json,
            alert_stage: stage,
            urgency_level: urgency,
            formatted_end_date: formattedDate,
            formatted_amount: amount,
            alert_message: `[${stage}] ${item.json.customer_name} 계약이 ${days}일 후(${formattedDate}) 만료됩니다.`
        }
    });
}

return results;

// 메시지 생성
const data = $input.item.json;

const subject = `⚠️ [${data.alert_stage}] ${data.customer_name} 계약 갱신 알림`;

const body = `
안녕하세요, ${data.sales_rep_name || '담당자'}님

고객사 "${data.customer_name}"의 계약이 ${data.days_remaining}일 후 만료됩니다.

������ 계약 정보
- 계약번호: ${data.contract_number}
- 서비스: ${data.service_type || '유지보수'}
- 만료일: ${data.formatted_end_date}
- 월 금액: ${data.formatted_amount}원
- 긴급도: ${data.urgency_level}

즉시 고객 컨택이 필요합니다.

감사합니다.
`;

return {
    json: {
        ...data,
        email_subject: subject,
        email_body: body
    }
};
